const a=JSON.parse(await tools.read_task_input({id:"prior-interface.json",pointer:""})).value;
store("prior",a);
const p=(name,type,binder_kind)=>({name,type,...(binder_kind?{binder_kind}:{})});
const ambient=[p("X","Type u"),p("instX","MetricSpace X","instance"),p("A","Set X")];
const sparams=[...ambient,p("s","ℝ"),p("hs","0 < s")];
const qparams=[...ambient,p("q","ℝ"),p("hq","0 < q"),p("hqzero","H q A = 0")];
const scale=[p("δ","ℝ"),p("hδ","0 < δ")];
const tolerance=[p("ε","ℝ"),p("hε","0 < ε")];
const prod="A ×ˢ YuiBasis.unitInterval";
const use=(parameters,args,expected)=>({parameters,args,expected});
const entry=(uses,level="u")=>[{levels:[level],uses}];
const raw=(space,set,exp,delta)=>`C (${exp}) (${delta}) (${set}) = ⨅ (U : ℕ → Set (${space})) (_ : (${set}) ⊆ ⋃ i, U i) (_ : ∀ i, Metric.ediam (U i) ≤ ENNReal.ofReal (${delta})), ∑' i, Metric.ediam (U i) ^ (${exp})`;
const sup=(set,exp)=>`H (${exp}) (${set}) = ⨆ (δ : ℝ) (_ : 0 < δ), C (${exp}) δ (${set})`;
const budgets=(set,exp,r,eps)=>`∃ (U : ℕ → Set X) (a : ℕ → ℝ), ((${set}) ⊆ ⋃ i, U i) ∧ (∀ i, 0 < a i ∧ a i ≤ (${r})) ∧ (∀ i, Metric.ediam (U i) ≤ ENNReal.ofReal (a i)) ∧ (∑' i, ENNReal.ofReal ((a i) ^ (${exp}))) < ENNReal.ofReal (${eps})`;
const cover=(exp,delta,eps)=>`∃ V : ℕ → Set (X × ℝ), (${prod} ⊆ ⋃ i, V i) ∧ (∀ i, Metric.ediam (V i) ≤ ENNReal.ofReal (${delta})) ∧ (∑' i, Metric.ediam (V i) ^ ((${exp}) + 1)) < ENNReal.ofReal (2 * (${eps}))`;
const normconclusion=a.steps[2].statement.split("0 < s →\n")[1];
const hullconclusion=a.steps[4].statement.split("(∀ i, Metric.ediam (V i) ≤ ENNReal.ofReal δ) →\n")[1];
const boundsconclusion=a.steps[9].statement.split("dimH A ≠ ⊤ →\n")[1];
const configs={
T004:{T003:entry([
use(sparams,["X","A","s","hs"],normconclusion),
use([...sparams,p("r","ℝ"),p("hr","0 < r")],["X","A","s","hs",1,"r / 2","half_pos hr"],raw("X","A","s","r / 2"))
])},
T006:{
T004:entry([
use([...sparams,...scale],["X","A","s","hs",1,"δ","hδ"],raw("X","A","s","δ")),
use([...sparams,...scale],["X × ℝ",prod,"s + 1","add_pos hs zero_lt_one",1,"δ","hδ"],raw("X × ℝ",prod,"s + 1","δ")),
use(sparams,["X","A","s","hs",2,2,1],sup("A","s")),
use(sparams,["X × ℝ",prod,"s + 1","add_pos hs zero_lt_one",2,2,1],sup(prod,"s + 1"))
]),
T005:entry([use([p("X","Type u"),p("instX","MetricSpace X","instance"),p("V","ℕ → Set (X × ℝ)"),...scale,p("hV","∀ i, Metric.ediam (V i) ≤ ENNReal.ofReal δ")],["X","V","δ","hδ","hV"],hullconclusion)])
},
T007:{T004:entry([use([...qparams,...scale,...tolerance],["X","A","q","hq",2,2,2,"hqzero","min 1 δ","ε","lt_min zero_lt_one hδ","hε"],budgets("A","q","min 1 δ","ε"))])},
T008:{
T004:entry([
use([...qparams,...scale],["X × ℝ",prod,"q + 1","add_pos hq zero_lt_one",1,"δ","hδ"],raw("X × ℝ",prod,"q + 1","δ")),
use(qparams,["X × ℝ",prod,"q + 1","add_pos hq zero_lt_one",2,2,1],sup(prod,"q + 1"))
]),
T007:entry([use([...qparams,...scale,...tolerance],["X","A","q","hq","hqzero","δ","ε","hδ","hε"],cover("q","δ","ε"))])
},
T010:{
T008:entry([use([...ambient,p("q","ℝ"),p("hq_gt","(dimH A).toReal < q"),p("hqzero","H q A = 0")],["X","A","q","lt_of_le_of_lt ENNReal.toReal_nonneg hq_gt","hqzero",1],`H (q + 1) (${prod}) = 0`)]),
T009:entry([use([...ambient,p("hA","A.Nonempty")],["X","A","hA"],`1 ≤ dimH (${prod})`)])
},
T011:{
T006:entry([use([...sparams,p("hsD","s < (dimH A).toReal")],["X","A","s","hs",2],`H s A ≤ H (s + 1) (${prod})`)]),
T010:entry([use([...ambient,p("hA","A.Nonempty"),p("hfinite","dimH A ≠ ⊤")],["X","A","hA","hfinite"],boundsconclusion)])
},
T014:{
T011:entry([
use([],["YuiBasis.Ambient n","E","h_H001","h_T001.2",1],`dimH (E ×ˢ YuiBasis.unitInterval) = dimH E + 1`),
use([],["YuiBasis.Ambient n","E","h_H001","h_T001.2",2],`dimH (E ×ˢ YuiBasis.unitInterval) ≠ ⊤`)
],"0"),
T013:[{levels:[],uses:[use([],[2,2,2,2,"E ×ˢ YuiBasis.unitInterval"],`dimH (appendCoord n '' (E ×ˢ YuiBasis.unitInterval)) = dimH (E ×ˢ YuiBasis.unitInterval)`)]}]
}
};
const notes={
T004:" Recorded applications specialize T003 to X,A,s,hs and its cover formula to r/2 with half_pos hr; these are the same bound variables and positivity condition used in S003–S004.",
T006:" The application records separately check N101's raw formula on X,A,s and on X×ℝ,A×I,s+1 at δ, and both supremum equalities, with s+1>0 obtained from hs. The hull application uses the arbitrary cover V and its already assumed δ-bound. Probe-local parameters reproduce these in-scope variables and hypotheses; they are not public assumptions.",
T007:" The recorded budget projection is N101.2.2.2 at X,A,q,hq, then hqzero,r=min(1,δ),ε; lt_min zero_lt_one hδ proves r>0 and hε is the original tolerance condition.",
T008:" The recorded applications check the chosen product cover at each δ,ε and N101's raw infimum and supremum at X×ℝ,A×I,q+1. All conditions are the original q,δ,ε positivity hypotheses.",
T010:" The T008 record uses the arbitrary q>D=(dimH A).toReal from S021. Its positivity follows from toReal_nonneg; hqzero denotes the local zero-measure fact proved there by the native critical-exponent implication, not an additional assumption. Projection 1 selects its measure conclusion. T009 is applied to the original nonempty A.",
T011:" The recorded N102 use is at X,A and the arbitrary 0<s<D introduced in S024, selecting its measure inequality. The T010 application discharges exactly nonemptiness and finite input dimension, giving the previously proved finite upper and lower bounds.",
T014:" The recorded N105 application supplies Ambient n and E, h_H001 and h_T001.2; projections separately check the dimension equality and product finiteness. The N106 application projects its preservation clause and applies it to E×I."
};
const patches=[];
for(let i=0;i<a.steps.length;i++){
const s=a.steps[i];
if(configs[s.id]){
patches.push({op:"replace",path:`/steps/${i}/input_instances`,value:configs[s.id]});
patches.push({op:"replace",path:`/steps/${i}/explanation`,value:s.explanation+notes[s.id]});
}
}
store("repairPatches",patches);
text(await tools.check_draft({artifact:{base_input:"prior-interface.json",patches}}));

let ps=load("repairPatches");
const replace=v=>{
if(typeof v==="string")return v.replaceAll("δ","delta").replaceAll("ε","eps");
if(Array.isArray(v))return v.map(replace);
if(v&&typeof v==="object")return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,replace(x)]));
return v;
};
ps=ps.filter(p=>p.path.endsWith("/input_instances")).map(replace);
store("asciiPatches",ps);
text(await tools.check_draft({artifact:{base_candidate:5,patches:ps}}));
